#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, m;
    cin >> n >> m;

    long long minimum = max(0LL, n - 2 * m);

    long long low = 0, high = n;
    while (low < high) {
        long long mid = low + (high - low) / 2;
        if (mid * (mid - 1) / 2 >= m)
            high = mid;
        else
            low = mid + 1;
    }

    long long maximum = n - low;
    cout << minimum << ' ' << maximum;

    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;

    vector<int> visited(n, 0);

    for (int i = 0; i < m; ++i) {
        if (i < n) visited[i] = 1;
        if (n - 1 - i >= 0) visited[n - 1 - i] = 1;
    }

    int count = 0;
    for (int value : visited) {
        if (value == 0) ++count;
    }

    fill(visited.begin(), visited.end(), 0);

    for (int i = 0; i < m; ++i) {
        if (i < n) visited[i] = 1;
        if (i + 1 < n) visited[i + 1] = 1;
    }

    int count2 = 0;
    for (int value : visited) {
        if (value == 0) ++count2;
    }

    cout << count << ' ' << count2;
    return 0;
}

